{"implementation":"def solve(case):
    segments = case.get("segments", [])
    budget = int(case.get("budget", 0))

    n = len(segments)
    allocations = [0] * n

    # Start from declared minimums when possible. If the budget cannot cover all
    # minimums, fund the most important segments first while preserving caps.
    minimums = [int(seg.get("minimum", 0)) for seg in segments]
    capacities = [int(seg.get("capacity", 0)) for seg in segments]
    importances = [int(seg.get("importance", 0)) for seg in segments]

    min_total = sum(min(m, c) for m, c in zip(minimums, capacities))

    if budget >= min_total:
        allocations = [min(m, c) for m, c in zip(minimums, capacities)]
        remaining = budget - sum(allocations)
    else:
        remaining = budget

    order = sorted(range(n), key=lambda i: (-importances[i], i))

    if budget < min_total:
        for i in order:
            if remaining <= 0:
                break
            give = min(minimums[i], capacities[i], remaining)
            allocations[i] += give
            remaining -= give
    else:
        for i in order:
            if remaining <= 0:
                break
            room = max(0, capacities[i] - allocations[i])
            give = min(room, remaining)
            allocations[i] += give
            remaining -= give

    by_name = {}
    for seg, amount in zip(segments, allocations):
        by_name[seg.get("name")] = int(amount)

    return {
        "allocations": [int(x) for x in allocations],
        "by_name": by_name,
        "total": int(sum(allocations)),
    }
"}
